package com.nigson.commerce.payment;

import java.util.*;
import java.time.*;
import java.math.BigDecimal;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.*;
import com.nigson.commerce.order.OrderPolicy;
import com.nigson.commerce.platform.*;
import com.nigson.commerce.reward.RewardOperations;
import com.nigson.commerce.payment.internal.infrastructure.external.paystack.PaystackAdapter;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.ProviderHttp;
import tools.jackson.databind.JsonNode;

/** An uncertain refund is inspected by its stored business identity, never resubmitted. */
public final class RefundCoordinator implements RefundOperations {
 private record Work(UUID id,UUID order,UUID attempt,String reference,String transactionId,String businessReference,String amount,String providerId,String state,long version,Instant updatedAt){}
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final PaystackAdapter provider;private final OrderPolicy binding;private final PaymentPolicy policy;private final String integration;private final AuditWriter audit;private final PlatformStore events;private final RewardOperations rewards;private final Clock clock;private final io.micrometer.core.instrument.MeterRegistry metrics;
 public RefundCoordinator(JdbcTemplate jdbc,PlatformTransactionManager manager,PaystackAdapter provider,OrderPolicy binding,PaymentPolicy policy,String integration,AuditWriter audit,PlatformStore events,RewardOperations rewards,Clock clock,io.micrometer.core.instrument.MeterRegistry metrics){this.jdbc=jdbc;tx=new TransactionTemplate(manager);tx.setTimeout(2);this.provider=provider;this.binding=binding;this.policy=policy;this.integration=integration;this.audit=audit;this.events=events;this.rewards=rewards;this.clock=clock;this.metrics=metrics;if(policy.enabled()&&(provider==null||!binding.enabled()||integration==null||!integration.matches("[1-9][0-9]{0,18}")))throw new IllegalArgumentException("PAYSTACK_REFUND_ACCOUNT_REQUIRED");}
 private void outside(){policy.require();if(provider==null)throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);if(TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("PROVIDER_CALL_INSIDE_TRANSACTION");}
 private Work locked(UUID refund){jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");var parent=jdbc.queryForList("SELECT order_id FROM commerce.refund WHERE id=?",refund);if(parent.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);UUID order=(UUID)parent.getFirst().get("order_id");var orders=jdbc.queryForList("SELECT currency_code,grand_total,carrier_snapshot::text FROM commerce.sales_order WHERE id=? FOR UPDATE",order);if(orders.size()!=1)throw PaymentValues.rule();var owned=orders.getFirst();binding.require(EventCodec.JSON.readTree(owned.get("carrier_snapshot").toString()).path("mode").asString());var rows=jdbc.queryForList("SELECT r.*,a.reference,a.provider,a.merchant_account,a.provider_mode,a.expected_amount,a.currency_code AS attempt_currency,a.state AS attempt_state,a.verified_at,t.settled_amount,t.currency_code AS settled_currency,t.provider_mode AS settled_mode,t.provider_status,t.provider_transaction_id FROM commerce.refund r JOIN commerce.payment_attempt a ON a.id=r.attempt_id JOIN commerce.payment_transaction t ON t.attempt_id=a.id WHERE r.id=? AND a.order_id=r.order_id FOR UPDATE OF r,a",refund);if(rows.size()!=1)throw PaymentValues.rule();var r=rows.getFirst();if(!r.get("provider").equals("PAYSTACK")||!r.get("merchant_account").equals(binding.merchantAccount())||!r.get("provider_mode").equals(binding.mode())||!r.get("settled_mode").equals(binding.mode())||!r.get("attempt_state").equals("SUCCEEDED")||r.get("verified_at")==null||!r.get("provider_status").equals("success")||!owned.get("currency_code").equals("NGN")||!r.get("currency_code").equals("NGN")||!r.get("settled_currency").equals("NGN")||!r.get("attempt_currency").equals("NGN")||((BigDecimal)r.get("expected_amount")).compareTo((BigDecimal)owned.get("grand_total"))!=0||((BigDecimal)r.get("settled_amount")).compareTo((BigDecimal)owned.get("grand_total"))!=0)throw PaymentValues.rule();BigDecimal active=jdbc.queryForObject("SELECT coalesce(sum(amount),0) FROM commerce.refund WHERE order_id=? AND state NOT IN ('FAILED','REJECTED')",BigDecimal.class,order);if(active.compareTo((BigDecimal)r.get("settled_amount"))>0||((BigDecimal)r.get("amount")).compareTo((BigDecimal)r.get("settled_amount"))>0)throw PaymentValues.rule();return new Work(refund,order,(UUID)r.get("attempt_id"),r.get("reference").toString(),r.get("provider_transaction_id").toString(),r.get("provider_reference").toString(),PaymentValues.money(((BigDecimal)r.get("amount")).stripTrailingZeros().toPlainString(),true),(String)r.get("provider_refund_id"),r.get("state").toString(),((Number)r.get("version")).longValue(),((java.sql.Timestamp)r.get("updated_at")).toInstant());}
 private void change(Work before,String state,String providerId,UUID correlation){if(before.version()==Long.MAX_VALUE)throw PaymentValues.rule();jdbc.update("UPDATE commerce.refund SET state=?,provider_refund_id=coalesce(?,provider_refund_id),version=version+1,updated_at=?,updated_by='refund-coordinator' WHERE id=?",state,providerId,java.sql.Timestamp.from(clock.instant()),before.id());audit.append("refund-coordinator",AuditValues.ActorKind.SYSTEM,Set.of("APPROVED","SUBMITTING").contains(before.state())?AuditValues.Action.REFUND_SUBMISSION:AuditValues.Action.REFUND_VERIFICATION,AuditValues.Resource.REFUND,before.id(),correlation,AuditValues.Reason.RECONCILIATION,Map.of("state",before.state(),"version",before.version()),Map.of("state",state,"version",before.version()+1,"amount",before.amount(),"currency","NGN","providerMode",binding.mode()),null);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.refund.outcomes","state",state).increment();}});}
 private String identifier(JsonNode value){if(value==null||!(value.isIntegralNumber()||binding.mode().equals("MOCK")&&value.isString()))throw PaymentValues.rule();String id=value.isString()?value.asString():value.toString();if(!id.matches("[A-Za-z0-9][A-Za-z0-9_-]{0,99}")||id.equals("0"))throw PaymentValues.rule();return id;}
 private String verifiedId(Work work,JsonNode data){if(data==null||!data.isObject()||!data.path("domain").asString().equals(binding.mode().equals("LIVE")?"live":"test")||!data.path("currency").asString().equals("NGN")||!data.path("amount").isIntegralNumber()||!data.path("amount").canConvertToLong()||data.path("amount").asLong()!=PaystackAdapter.kobo(work.amount())||!data.path("integration").isIntegralNumber()||!data.path("integration").toString().equals(integration)||!data.path("merchant_note").asString().equals(work.businessReference())||!Set.of("pending","processing","processed","failed","needs-attention").contains(data.path("status").asString()))throw PaymentValues.rule();JsonNode transaction=data.path("transaction");String transactionId=identifier(transaction.isObject()?transaction.get("id"):transaction);if(!transactionId.equals(work.transactionId()))throw PaymentValues.rule();String id=identifier(data.get("id"));if(work.providerId()!=null&&!work.providerId().equals(id))throw PaymentValues.rule();return id;}
 public void submit(UUID refund,UUID correlation){outside();Work work=tx.execute(status->{var current=locked(refund);if(!current.state().equals("APPROVED")){if(current.state().equals("SUBMITTING")&&!current.updatedAt().plusSeconds(30).isAfter(clock.instant()))change(current,"UNKNOWN",null,correlation);return null;}if(jdbc.queryForObject("SELECT approved_by IS NULL FROM commerce.refund WHERE id=?",Boolean.class,refund))throw PaymentValues.rule();change(current,"SUBMITTING",null,correlation);return current;});if(work==null)return;String providerId=null;try{providerId=verifiedId(work,provider.refund(work.reference(),work.amount(),work.businessReference()));}catch(ProviderHttp.Failure|Problem.Failure|IllegalArgumentException uncertain){providerId=null;}final String accepted=providerId;tx.executeWithoutResult(status->{var current=locked(refund);if(!current.state().equals("SUBMITTING"))return;change(current,accepted==null?"UNKNOWN":"PENDING",accepted,correlation);});}
 public void inspect(UUID refund,UUID correlation){outside();Work work=tx.execute(status->{var current=locked(refund);if(Set.of("REQUESTED","APPROVED","SUCCEEDED","FAILED","REJECTED").contains(current.state()))return null;if(current.state().equals("SUBMITTING")){if(current.updatedAt().plusSeconds(30).isAfter(clock.instant()))return null;change(current,"UNKNOWN",null,correlation);}return current;});if(work==null)return;JsonNode verified;String id;try{String lookup=work.providerId();if(lookup==null){JsonNode found=null;boolean exhausted=false;long deadline=System.nanoTime()+Duration.ofSeconds(10).toNanos();for(int page=1;page<=10;page++){if(System.nanoTime()>=deadline)throw PaymentValues.rule();var rows=provider.refunds(work.transactionId(),page);if(!rows.isArray()||rows.size()>100)throw PaymentValues.rule();for(var row:rows)if(row.path("merchant_note").asString().equals(work.businessReference())){if(found!=null)throw PaymentValues.rule();verifiedId(work,row);found=row;}if(rows.size()<100){exhausted=true;break;}}if(!exhausted||found==null)throw PaymentValues.rule();lookup=identifier(found.get("id"));}verified=provider.refundStatus(lookup);id=verifiedId(work,verified);}catch(ProviderHttp.Failure|Problem.Failure|IllegalArgumentException uncertain){tx.executeWithoutResult(status->{var current=locked(refund);if(!Set.of("SUCCEEDED","FAILED","REJECTED","UNKNOWN").contains(current.state()))change(current,"UNKNOWN",null,correlation);});return;}final JsonNode outcome=verified;final String actual=id;tx.executeWithoutResult(status->{var current=locked(refund);if(Set.of("SUCCEEDED","FAILED","REJECTED").contains(current.state()))return;String providerState=outcome.path("status").asString();String state=providerState.equals("processed")?"SUCCEEDED":providerState.equals("failed")?"FAILED":providerState.equals("needs-attention")?"UNKNOWN":"PENDING";change(current,state,actual,correlation);if(state.equals("SUCCEEDED"))settled(current,correlation);else if(state.equals("FAILED"))restore(current);});}
 private void settled(Work work,UUID correlation){var row=jdbc.queryForList("SELECT status,payment_status,refunded_total,grand_total,version,party_id,organization_id FROM commerce.sales_order WHERE id=?",work.order()).getFirst();BigDecimal total=jdbc.queryForObject("SELECT coalesce(sum(amount),0) FROM commerce.refund WHERE order_id=? AND state='SUCCEEDED'",BigDecimal.class,work.order());BigDecimal before=total.subtract(new BigDecimal(work.amount()));if(before.compareTo((BigDecimal)row.get("refunded_total"))!=0||total.compareTo((BigDecimal)row.get("grand_total"))>0||((Number)row.get("version")).longValue()==Long.MAX_VALUE)throw PaymentValues.rule();boolean full=total.compareTo((BigDecimal)row.get("grand_total"))==0;String after=full?"REFUNDED":row.get("status").toString();jdbc.update("UPDATE commerce.sales_order SET refunded_total=?,payment_status=?,status=?,version=version+1,updated_at=?,updated_by='refund-coordinator' WHERE id=?",total,full?"REFUNDED":"PARTIALLY_REFUNDED",after,java.sql.Timestamp.from(clock.instant()),work.order());jdbc.update("INSERT INTO commerce.order_status_history(id,created_by,order_id,previous_status,new_status,reason) VALUES (?,'refund-coordinator',?,?,?,'Independently verified provider refund')",EventCodec.uuid7(clock.instant()),work.order(),row.get("status"),after);var event=new LinkedHashMap<String,Object>();Instant now=clock.instant();event.put("event_id",EventCodec.uuid7(now));event.put("event_type","refund.succeeded.v1");event.put("schema_version",1);event.put("producer","commerce");event.put("occurred_at",now);event.put("aggregate_id",work.id());event.put("aggregate_version",work.version()+1);event.put("organization_id",row.get("organization_id"));event.put("correlation_id",correlation);event.put("traceparent",null);event.put("payload",Map.of("refund_id",work.id(),"order_id",work.order(),"currency","NGN","amount",work.amount()));rewards.refundSettled(work.id(),correlation);events.append(EventCodec.JSON.writeValueAsString(event),"refund-coordinator");}
 private void restore(Work work){var rows=jdbc.queryForList("SELECT status,version,grand_total FROM commerce.sales_order WHERE id=?",work.order());var order=rows.getFirst();if(!order.get("status").equals("REFUNDING"))return;BigDecimal approved=jdbc.queryForObject("SELECT coalesce(sum(amount),0) FROM commerce.refund WHERE order_id=? AND state IN ('APPROVED','SUBMITTING','PENDING','UNKNOWN','SUCCEEDED')",BigDecimal.class,work.order());if(approved.compareTo((BigDecimal)order.get("grand_total"))==0)return;if(((Number)order.get("version")).longValue()==Long.MAX_VALUE)throw PaymentValues.rule();var history=jdbc.queryForList("SELECT previous_status FROM commerce.order_status_history WHERE order_id=? AND new_status='REFUNDING' AND previous_status<>'REFUNDING' ORDER BY created_at DESC,id DESC LIMIT 1",work.order());if(history.size()!=1||!Set.of("PAID","PROCESSING","PAYMENT_HOLD").contains(history.getFirst().get("previous_status")))throw PaymentValues.rule();String status=history.getFirst().get("previous_status").toString();jdbc.update("UPDATE commerce.sales_order SET status=?,version=version+1,updated_at=?,updated_by='refund-coordinator' WHERE id=?",status,java.sql.Timestamp.from(clock.instant()),work.order());jdbc.update("INSERT INTO commerce.order_status_history(id,created_by,order_id,previous_status,new_status,reason) VALUES (?,'refund-coordinator',?,'REFUNDING',?,'Authoritative refund failure retained')",EventCodec.uuid7(clock.instant()),work.order(),status);}
}
